<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import { gsap } from 'gsap'

const sceneRef = ref(null)
let ctx

onMounted(() => {
  if (!sceneRef.value) return
  ctx = gsap.context(() => {
    // Woman idle breathing — subtle Y bob
    gsap.to('#woman-body', {
      y: -1.5, duration: 1.8, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })
    gsap.to('#woman-head', {
      y: -2, duration: 1.8, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })
    gsap.to('#woman-legs', {
      y: -0.5, duration: 1.8, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })

    // Woman arm reaching toward machine — subtle gesture
    gsap.to('#woman-arm', {
      x: 0.8, y: -0.6, duration: 2.2, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })

    // Second person idle
    gsap.to('#person2-body', {
      y: -1.2, duration: 2, ease: 'sine.inOut', repeat: -1, yoyo: true, delay: 0.3,
    })
    gsap.to('#person2-head', {
      y: -1.6, duration: 2, ease: 'sine.inOut', repeat: -1, yoyo: true, delay: 0.3,
    })
    gsap.to('#person2-legs', {
      y: -0.4, duration: 2, ease: 'sine.inOut', repeat: -1, yoyo: true, delay: 0.3,
    })

    // Machine screens glow pulse
    gsap.to('.machine-screen', {
      opacity: 0.85, duration: 1.5, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })

    // Machine indicator lights blink
    gsap.to('.light-blue', {
      opacity: 0.5, duration: 0.8, ease: 'power1.inOut', repeat: -1, yoyo: true,
    })
    gsap.to('.light-pink', {
      opacity: 0.5, duration: 1.1, ease: 'power1.inOut', repeat: -1, yoyo: true, delay: 0.3,
    })
    gsap.to('.light-yellow', {
      opacity: 0.4, duration: 0.9, ease: 'power1.inOut', repeat: -1, yoyo: true, delay: 0.6,
    })

    // Plants gentle sway
    gsap.to('.plant-leaf', {
      rotation: 2, duration: 2.5, ease: 'sine.inOut', repeat: -1, yoyo: true,
      transformOrigin: '50% 100%',
    })
    gsap.to('.plant-leaf-2', {
      rotation: -1.5, duration: 3, ease: 'sine.inOut', repeat: -1, yoyo: true,
      transformOrigin: '50% 100%', delay: 0.5,
    })

    // Pot plants subtle float
    gsap.to('.pot-plant-left', {
      y: -0.8, duration: 3, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })
    gsap.to('.pot-plant-right', {
      y: -0.8, duration: 3.2, ease: 'sine.inOut', repeat: -1, yoyo: true, delay: 0.4,
    })

    // Phone screen content shimmer
    gsap.to('#phone-screen-content', {
      opacity: 0.7, duration: 2, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })

    // Vending machine item dispensing hint
    gsap.to('#machine-knob-1', {
      rotation: 5, duration: 3, ease: 'sine.inOut', repeat: -1, yoyo: true,
      svgOrigin: '261.037 91.922',
    })
    gsap.to('#machine-knob-2', {
      rotation: -5, duration: 3.5, ease: 'sine.inOut', repeat: -1, yoyo: true,
      svgOrigin: '262.865 93.096',
    })

    // Ambient floor tile shimmer — staggered subtle opacity
    gsap.to('.floor-tile', {
      opacity: 0.08, duration: 4, ease: 'sine.inOut', repeat: -1, yoyo: true,
      stagger: { each: 0.3, from: 'random' },
    })

    // Blue bar accent pulse
    gsap.to('.blue-accent', {
      opacity: 0.7, duration: 2.5, ease: 'sine.inOut', repeat: -1, yoyo: true,
    })

    // Wire/cable subtle sway
    gsap.to('.cable-line', {
      attr: { 'stroke-dashoffset': 10 },
      duration: 3, ease: 'none', repeat: -1,
    })

  }, sceneRef.value)
})

onUnmounted(() => {
  ctx?.revert()
})
</script>

